from collections import deque

def find_rects(g):
    H,W=len(g),len(g[0])
    cover=[[False]*W for _ in range(H)]
    for r in range(H):
        c=0
        while c<W:
            v=g[r][c]; c2=c
            while c2<W and g[r][c2]==v: c2+=1
            w=c2-c
            h=1
            while r+h<H and all(g[r+h][x]==v for x in range(c,c2)):
                h+=1
            if w>=2 and h>=2:
                for i in range(r,r+h):
                    for j in range(c,c+w):
                        cover[i][j]=True
            c=c2
    return cover

def transform(g):
    H,W=len(g),len(g[0])
    cov=find_rects(g)
    out=[row[:] for row in g]
    q=deque()
    for r in range(H):
        for c in range(W):
            if cov[r][c]:
                q.append((r,c,g[r][c],0))
    seen=set((r,c) for r in range(H) for c in range(W) if cov[r][c])
    while q:
        r,c,col,d=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen:
                seen.add((nr,nc))
                out[nr][nc]=col
                q.append((nr,nc,col,d+1))
    return out

