from collections import deque, Counter

def transform(g):
    H,W=len(g),len(g[0])
    # components
    comp=[[-1]*W for _ in range(H)]; comps=[]
    for r in range(H):
        for c in range(W):
            if comp[r][c]<0:
                v=g[r][c]; cid=len(comps); q=deque([(r,c)]); comp[r][c]=cid; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and comp[na][nb]<0 and g[na][nb]==v:
                            comp[na][nb]=cid; q.append((na,nb))
                comps.append((v,cells))
    global_cnt=Counter(g[r][c] for r in range(H) for c in range(W))
    noise_ids={i for i,(v,cells) in enumerate(comps) if len(cells)<=2}
    out=[row[:] for row in g]
    # for each noise comp, gather adjacent non-noise colors
    pending=[]
    for i in noise_ids:
        v,cells=comps[i]
        cnt=Counter()
        for (a,b) in cells:
            for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                na,nb=a+da,b+db
                if 0<=na<H and 0<=nb<W and comp[na][nb] not in noise_ids:
                    cnt[g[na][nb]]+=1
        pending.append((i,v,cells,cnt))
    bg=global_cnt.most_common(1)[0][0]
    for i,v,cells,cnt in pending:
        if not cnt:
            fill=bg
        else:
            mx=max(cnt.values()); tops=[k for k,x in cnt.items() if x==mx]
            fill=tops[0] if len(tops)==1 else bg
        for (a,b) in cells: out[a][b]=fill
    return out

